const input = $input.item.json.body ?? $input.item.json;
const { action = 'preview', form_data, ...raw } = input;
const request = form_data ?? raw;
const allowed = new Set(['local_operator_id','title','idempotency_key','intent','forbid','selling_points','target_words','chapter_words','characters','world_assets','relations','segment_promises']);
const required = [...allowed];
const invalid = !request || typeof request !== 'object' || Array.isArray(request) || Object.keys(request).some((key) => !allowed.has(key));
if (invalid) return [{ json: { route: 'preview', preview_request: request, status: 'preview', missing_fields: ['valid_request'] } }];
const missing = required.filter((key) => !Object.hasOwn(request, key));
if (action === 'confirm_create' && !missing.length) return [{ json: { route: 'confirm', rpc_request: request } }];
return [{ json: { route: 'preview', preview_request: request, status: 'preview', missing_fields: missing } }];

const source = $('FP001-02 closed validation and route').item.json;
const unavailable = [['skill_available', 'ACTIVE_SKILL_UNAVAILABLE'], ['config_available', 'ACTIVE_CONFIG_UNAVAILABLE'], ['budget_available', 'ACTIVE_BUDGET_UNAVAILABLE']].find(([field]) => !$input.item.json[field]);
if (unavailable) return [{ json: { route: 'blocked', status: 'BLOCKED', code: unavailable[1], message: 'The preview dependencies are not available.' } }];
return [{ json: { route: 'agent', preview_request: source.preview_request, missing_fields: source.missing_fields } }];
